namespace JobSearch.Api.Search;

public sealed class CursorOptions
{
    public const string DevelopmentKey = "ZGV2ZWxvcG1lbnQtb25seS1uZXZlci11c2UtaW4tcHJvZHVjdGlvbiE=";
    public string ActiveKeyId { get; set; } = "current";
    public Dictionary<string, string> Keys { get; set; } = new();
    public int LifetimeMinutes { get; set; } = 15;
}

public sealed class CursorOptionsValidator(IHostEnvironment environment) : IValidateOptions<CursorOptions>
{
    public ValidateOptionsResult Validate(string? name, CursorOptions o)
    {
        if (o.LifetimeMinutes is < 1 or > 60 || o.Keys.Count is < 1 or > 4 || !o.Keys.ContainsKey(o.ActiveKeyId))
            return ValidateOptionsResult.Fail("Cursor configuration is invalid.");
        foreach (var key in o.Keys)
        {
            if (key.Key.Length is < 1 or > 32 || key.Key.Any(c => !char.IsAsciiLetterOrDigit(c) && c != '-'))
                return ValidateOptionsResult.Fail("Cursor key identifiers are invalid.");
            try
            {
                if (Convert.FromBase64String(key.Value).Length < 32
                    || (!environment.IsDevelopment() && key.Value == CursorOptions.DevelopmentKey))
                    return ValidateOptionsResult.Fail("Cursor signing keys must be externally configured secure keys.");
            }
            catch (FormatException)
            {
                return ValidateOptionsResult.Fail("Cursor signing keys must be base64 encoded.");
            }
        }
        return ValidateOptionsResult.Success;
    }
}
using System.Globalization;
using Microsoft.Extensions.Primitives;
namespace JobSearch.Api.Contracts;

public sealed class QueryReader(TimeProvider clock)
{
    public DateOnly TodayUtc() => DateOnly.FromDateTime(clock.GetUtcNow().UtcDateTime);

    public static bool Available(DateOnly closingDate, DateOnly today) => closingDate > today;

    public static bool TryId(string value, out Guid id) => Guid.TryParseExact(value, "D", out id) && id != Guid.Empty;

    public QueryReadResult Read(IEnumerable<KeyValuePair<string, StringValues>> parameters)
    {
        var values = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var p in parameters)
        {
            if (!new[] { "q", "department", "location", "limit", "sort", "cursor" }.Contains(p.Key)
                || p.Value.Count != 1
                || !values.TryAdd(p.Key, p.Value.ToString()))
                return new(null, "invalid_query");
        }
        try
        {
            var q = Filter(values.GetValueOrDefault("q", ""), 200);
            var department = Filter(values.GetValueOrDefault("department", ""), 100);
            var location = Filter(values.GetValueOrDefault("location", ""), 100);
            var limit = 20;
            if (values.TryGetValue("limit", out var raw)
                && (!int.TryParse(raw, NumberStyles.None, CultureInfo.InvariantCulture, out limit) || limit is < 1 or > 50))
                throw new FormatException();
            var sort = values.GetValueOrDefault("sort", "newest");
            if (sort is not ("newest" or "closing-soon")) throw new FormatException();
            var cursor = values.GetValueOrDefault("cursor");
            if (cursor is not null
                && (cursor.Length is 0 or > 2048 || cursor.Any(char.IsWhiteSpace) || cursor.Any(char.IsControl)))
                throw new FormatException();
            return new(new(q, department, location, limit, sort, cursor), null);
        }
        catch (FormatException) { return new(null, "invalid_query"); }
    }

    private static string? Filter(string value, int maximum)
    {
        var trimmed = value.Trim();
        if (trimmed.Length > maximum || trimmed.Any(char.IsControl)) throw new FormatException();
        return trimmed.Length == 0 ? null : trimmed;
    }
}

using System.Security.Cryptography;
using System.Text.Json;
using Microsoft.Extensions.Options;
using JobSearch.Api.Contracts;
namespace JobSearch.Api.Search;

public sealed record PagePosition(long CreatedTicks, Guid Id, int ClosingDay);

public sealed record CursorPayload(
    int Version,
    string KeyId,
    string Binding,
    int Day,
    long Watermark,
    PagePosition Last,
    long IssuedTicks,
    long ExpiryTicks);

public sealed record CursorResult(CursorPayload? Payload, string? Error);

public sealed class CursorCodec(IOptions<CursorOptions> options)
{
    private static readonly string[] Fields =
        ["Version", "KeyId", "Binding", "Day", "Watermark", "Last", "IssuedTicks", "ExpiryTicks"];

    public static string Binding(SearchQuery query) => Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(new[]
    {
        query.Q,
        query.Department,
        query.Location,
        query.Limit.ToString(System.Globalization.CultureInfo.InvariantCulture),
        query.Sort
    })));

    public CursorPayload Start(SearchQuery query, DateTimeOffset now, long watermark) => new(
        1,
        options.Value.ActiveKeyId,
        Binding(query),
        DateOnly.FromDateTime(now.UtcDateTime).DayNumber,
        watermark,
        new(0, Guid.Empty, 0),
        now.UtcTicks,
        now.AddMinutes(options.Value.LifetimeMinutes).UtcTicks);

    public string Encode(CursorPayload payload)
    {
        var bytes = JsonSerializer.SerializeToUtf8Bytes(payload);
        var mac = HMACSHA256.HashData(Convert.FromBase64String(options.Value.Keys[payload.KeyId]), bytes);
        return Url(bytes) + "." + Url(mac);
    }

    public CursorResult Decode(string cursor, SearchQuery query, DateTimeOffset now)
    {
        if (cursor.Length is 0 or > 2048) return new(null, "invalid_cursor");
        try
        {
            var parts = cursor.Split('.');
            if (parts.Length != 2) return new(null, "invalid_cursor");
            var body = Unurl(parts[0]);
            var mac = Unurl(parts[1]);
            using var json = JsonDocument.Parse(body, new JsonDocumentOptions { MaxDepth = 4 });
            var root = json.RootElement;
            if (!Shape(root, Fields) || !Shape(root.GetProperty("Last"), ["CreatedTicks", "Id", "ClosingDay"]))
                return new(null, "invalid_cursor");
            var p = JsonSerializer.Deserialize<CursorPayload>(body)!;
            if (p.KeyId is null
                || !options.Value.Keys.TryGetValue(p.KeyId, out var secret)
                || !CryptographicOperations.FixedTimeEquals(mac, HMACSHA256.HashData(Convert.FromBase64String(secret), body)))
                return new(null, "invalid_cursor");
            if (p.Binding != Binding(query)
                || p.Watermark < 0
                || p.Day is < 0 or > 3652058
                || p.Last.ClosingDay is < 0 or > 3652058
                || p.Last.Id == Guid.Empty
                || p.Last.CreatedTicks is < 0 or > 3155378975999999999
                || p.IssuedTicks < 0
                || p.IssuedTicks > now.UtcTicks
                || p.ExpiryTicks <= p.IssuedTicks
                || p.ExpiryTicks - p.IssuedTicks > TimeSpan.FromHours(1).Ticks
                || p.ExpiryTicks > 3155378975999999999)
                return new(null, "invalid_cursor");
            return p.Version != 1 || now.UtcTicks >= p.ExpiryTicks ? new(null, "cursor_expired") : new(p, null);
        }
        catch (Exception ex) when (ex is FormatException or JsonException or InvalidOperationException or OverflowException)
        {
            return new(null, "invalid_cursor");
        }
    }

    private static bool Shape(JsonElement element, string[] fields) =>
        element.ValueKind == JsonValueKind.Object
        && element.EnumerateObject().Select(p => p.Name).Order().SequenceEqual(fields.Order());

    private static string Url(byte[] bytes) => Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');

    private static byte[] Unurl(string value)
    {
        if (value.Length == 0 || value.Any(c => !char.IsAsciiLetterOrDigit(c) && c != '-' && c != '_')) throw new FormatException();
        var bytes = Convert.FromBase64String(value.Replace('-', '+').Replace('_', '/').PadRight((value.Length + 3) / 4 * 4, '='));
        if (Url(bytes) != value) throw new FormatException();
        return bytes;
    }
}
