    image: rabbitmq:4.3.6-management@sha256:8dd6e3570ddaa2ef82a6c3a8950e79c1f73893adfbdddbc374fc1f1ac8a0f5dd
    # The Erlang node name must stay stable when a container is recreated against this volume.
    hostname: rabbitmq
    environment:
