      - "127.0.0.1:${RABBITMQ_MANAGEMENT_PORT:-15672}:15672"
    volumes:
      - rabbitmq-data:/var/lib/rabbitmq
    healthcheck:
      test: ["CMD", "rabbitmq-diagnostics", "-q", "check_running"]
      interval: 5s
      timeout: 5s
      retries: 12
      start_period: 15s
    stop_grace_period: 45s

  job-posting-migrate:
    image: job-board-posting-migrations:local
    build:
      context: ./API/job-posting-api
      target: migrations
    environment: *posting-db
    depends_on:
      postgres: {condition: service_healthy}
    restart: "no"

  job-search-migrate:
    image: job-board-search-migrations:local
    build:
      context: ./API/job-search.api
      target: migrations
    environment: *search-db
    depends_on:
      postgres: {condition: service_healthy}
    restart: "no"

  job-posting-api:
    image: job-board-posting-api:local
    build:
      context: ./API/job-posting-api
      target: api
    environment:
      <<: *posting-db
      ASPNETCORE_ENVIRONMENT: Production
      ASPNETCORE_HTTP_PORTS: "8080"
      JobPosting__BusinessTimeZone: ${JOB_POSTING_TIME_ZONE:-America/Toronto}
      RabbitMq__HostName: rabbitmq
      RabbitMq__Port: "5672"
      RabbitMq__UserName: ${RABBITMQ_USER:-jobboard}
      RabbitMq__Password: ${RABBITMQ_PASSWORD:-local-development-only-change-me}
    ports:
      - "127.0.0.1:${JOB_POSTING_API_PORT:-5000}:8080"
    depends_on:
      rabbitmq: {condition: service_healthy}
      job-posting-migrate: {condition: service_completed_successfully}
    stop_grace_period: 45s

  job-search-api:
    image: job-board-search-api:local
    build:
      context: ./API/job-search.api
      target: api
    environment:
      <<: *search-db
      ASPNETCORE_ENVIRONMENT: Production
      ASPNETCORE_HTTP_PORTS: "8080"
      Cursor__ActiveKeyId: current
      # Local-only default; set CURSOR_SIGNING_KEY to a fresh 32-byte base64 key for anything shared.
