      RabbitMq__HostName: rabbitmq
      RabbitMq__Port: "5672"
      RabbitMq__UserName: ${RABBITMQ_USER:-jobboard}
      RabbitMq__Password: ${RABBITMQ_PASSWORD:-local-development-only-change-me}
      RabbitMq__VirtualHost: /
    ports:
      - "127.0.0.1:${SEARCH_API_PORT:-5101}:8080"
    depends_on:
      rabbitmq: {condition: service_healthy}
      job-search-migrate: {condition: service_completed_successfully}
    stop_grace_period: 45s

volumes:
  postgres-data:
  rabbitmq-data:
